 [MenuItem("Tools/Out Scene Transfer/Inspect And Pause Import")]
 public static void Pause(){var b=new StringBuilder();try{if(EditorApplication.isPlaying)throw new Exception("Leave Play mode first");var s=SceneManager.GetActiveScene();b.AppendLine("active="+s.path+" dirty="+s.isDirty+" rootCount="+s.rootCount);var p=GraphicsSettings.currentRenderPipeline;b.AppendLine("pipeline="+AssetDatabase.GetAssetPath(p));foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))b.AppendLine("camera="+c.name+" pose="+c.transform.position.ToString("R"));if(!s.path.EndsWith("Forest_Ruins_Detailed_Study.unity"))throw new Exception("Unexpected active scene");Directory.CreateDirectory(W+"out_transfer_backup");File.Copy(s.path,W+"out_transfer_backup/Forest_Ruins_Detailed_Study.unity",true);File.Copy(AssetDatabase.GetAssetPath(p),W+"out_transfer_backup/TargetPipeline.asset.txt",true);AssetDatabase.DisallowAutoRefresh();b.AppendLine("autoRefreshPaused=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_target_inspection.txt",b.ToString());}
 [MenuItem("Tools/Out Scene Transfer/Resume And Import")]
 public static void Resume(){AssetDatabase.AllowAutoRefresh();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);File.WriteAllText(W+"out_import_requested.txt","requested=True");}
 static MonoBehaviour Component(Scene s,string type){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).FirstOrDefault(c=>c&&c.GetType().Name==type);}
 static void Call(MonoBehaviour c,string name){if(c)c.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)?.Invoke(c,null);}
 static void Capture(Camera source,string path){GameObject go=null;RenderTexture rt=null;Texture2D tex=null;var old=RenderTexture.active;try{go=new GameObject("CodexAtmospherePreview"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.CopyFrom(source);c.scene=source.gameObject.scene;c.enabled=false;c.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);EditorUtility.CopySerialized(source.GetUniversalAdditionalCameraData(),c.GetUniversalAdditionalCameraData());rt=new RenderTexture(1600,900,24,RenderTextureFormat.ARGB32);rt.antiAliasing=1;c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);File.WriteAllBytes(path,tex.EncodeToPNG());}finally{RenderTexture.active=old;if(go)UnityEngine.Object.DestroyImmediate(go);if(rt){rt.Release();UnityEngine.Object.DestroyImmediate(rt);}if(tex)UnityEngine.Object.DestroyImmediate(tex);}}
 [MenuItem("Tools/Out Scene Transfer/Configure And Verify Out Scene")]
 public static void Configure(){var b=new StringBuilder();var original=SceneManager.GetActiveScene();Scene imported=default;try{if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;if(!pipeline)throw new Exception("Target uses no URP");var renderer=AssetDatabase.LoadAssetAtPath<UniversalRendererData>(Renderer);if(!renderer)throw new Exception("Out renderer missing");var so=new SerializedObject(pipeline);var list=so.FindProperty("m_RendererDataList");int index=-1;for(int i=0;i<list.arraySize;i++)if(list.GetArrayElementAtIndex(i).objectReferenceValue==renderer)index=i;int defaultIndex=so.FindProperty("m_DefaultRendererIndex").intValue;if(index<0){index=list.arraySize;list.InsertArrayElementAtIndex(index);list.GetArrayElementAtIndex(index).objectReferenceValue=renderer;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(pipeline);AssetDatabase.SaveAssets();}b.AppendLine("outRendererIndex="+index+" existingDefaultRenderer="+defaultIndex+" existingScene="+original.path);
 imported=EditorSceneManager.OpenScene(Out,OpenSceneMode.Additive);SceneManager.SetActiveScene(imported);var roots=imported.GetRootGameObjects();int missingScripts=roots.SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));var renderers=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();int missingMeshes=roots.SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Count(f=>!f.sharedMesh);int missingMaterials=renderers.Sum(r=>r.sharedMaterials.Count(m=>!m||!m.shader));foreach(var camera in roots.SelectMany(g=>g.GetComponentsInChildren<Camera>(true)))camera.GetUniversalAdditionalCameraData().SetRenderer(index);
 var style=Component(imported,"MeadowPainterlyStyle");Call(style,"Apply");var air=Component(imported,"MeadowAtmosphere");Call(air,"UpdateClouds");var cameras=roots.SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).ToArray();var view=cameras.First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");EditorSceneManager.MarkSceneDirty(imported);if(!EditorSceneManager.SaveScene(imported))throw new Exception("Failed to save out scene");b.AppendLine("rootObjects="+roots.Length+" renderers="+renderers.Length+" missingScripts="+missingScripts+" missingMeshes="+missingMeshes+" missingMaterials="+missingMaterials+" terrain="+roots.SelectMany(g=>g.GetComponentsInChildren<Terrain>(true)).Count());
 Capture(view,O+"Out_scene_import_preview.png");int errors=0;foreach(var shader in renderers.SelectMany(r=>r.sharedMaterials).Where(m=>m).Select(m=>m.shader).Where(s=>s).Distinct())foreach(var message in ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity.ToString()=="Error")){errors++;b.AppendLine("SHADER "+shader.name+": "+message.message);}b.AppendLine("activeShaderErrors="+errors);if(missingScripts+missingMeshes+missingMaterials+errors>0)throw new Exception("Missing dependencies or shader errors");b.AppendLine("verified=True saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}finally{if(original.IsValid()&&original.isLoaded)SceneManager.SetActiveScene(original);if(imported.IsValid()&&imported.isLoaded)EditorSceneManager.CloseScene(imported,true);Selection.activeObject=AssetDatabase.LoadAssetAtPath<SceneAsset>(Out);EditorGUIUtility.PingObject(Selection.activeObject);b.AppendLine("activeSceneRestored="+SceneManager.GetActiveScene().path);}File.WriteAllText(W+"out_scene_import_checks.txt",b.ToString());}
